function renderCommands(){if(!$('#commands'))return;const list=commandData.filter(c=>(filter==='all'||filter==='first'&&c.status==='first'||c.category===filter)&&[c.name,c.description,c.example,c.options].join(' ').toLowerCase().includes(search.toLowerCase()));$('#command-count').textContent=`${list.length} of ${commandData.length} commands · 5 implemented in first build`;$('#commands').innerHTML=list.length?list.map(c=>`<article class="command-card"><div class="command-card-header"><h3>${c.name}</h3><span class="command-status ${c.status==='planned'?'planned':''}">${c.status==='first'?'First build':'Roadmap'}</span></div><p>${c.description}</p><div class="command-example"><code>${esc(c.example)}</code><button data-copy="${esc(c.example)}" aria-label="Copy ${c.name} example">Copy ↗</button></div><div class="command-option"><b>${esc(c.plan)}</b><br>${esc(c.options)}</div></article>`).join(''):'<div class="empty">No commands match. Try a different keyword or category.</div>';$$('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('Command example copied.');}catch{toast('Clipboard unavailable. Select the example text to copy it.');}});}
